  (run_id, workflow_name, stage_name, status, started_at, finished_at)
  VALUES (${pgStr('cleanup-' + getBusinessDate() + '-' + Date.now())}, '04 – Cleanup News-Tabellen', 'cleanup',
          'success', now(), now());`;
return { json: { ...$json, sql } };

